import { useState } from "react";

export default function ItemsList({ items, onToggleItem, onDeleteItem }) {
  let sortedItems = [...items];
  const { sortBy, setSortBy } = useState("input");
  sortedItems.sort((a, b) => {
    if (sortBy === "input") return a.id - b.id;
    if (sortBy === "packed") return a.packed - b.packed;
    if (sortBy === "description") return a.item.localeCompare(b.item);
  });

  function handlePackingItem(itemId) {
    onToggleItem(itemId);
  }

  function handleDeleteItem(itemId) {
    onDeleteItem(itemId);
  }
  return (
    <div className="list">
      <ul>
        {sortedItems.map((item) => (
          <li key={item.id}>
            <input
              type="checkbox"
              checked={item.packed}
              onChange={() => handlePackingItem(item.id)}
            />
            <span>{item.item}</span>
            <button onClick={() => handleDeleteItem(item.id)}>❌</button>
          </li>
        ))}
      </ul>
      <div className="actions">
        <select value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
          <option value="input">Sort by Input Order</option>
          <option value="packed">Sort by Packed Status</option>
          <option value="description">Sort by Description</option>
        </select>
        <button>Clear List</button>
      </div>
    </div>
  );
}
